select case when duration_sec >= 467 then 'HIGH' else 'LOW' end as duration_sec_tier, date_trunc('month', event_time) as activity_month, count(case when page = '/product' then 1 end) as product_count, round(avg(duration_sec), 2) as avg_duration_sec, min(event_time) as started_at, grouping_id() as grouping_id from web_events group by grouping sets ((case when duration_sec >= 467 then 'HIGH' else 'LOW' end, date_trunc('month', event_time)), (case when duration_sec >= 467 then 'HIGH' else 'LOW' end), ());
